const lintOrphanCount = `-- name: LintOrphanCount :one

WITH candidates AS MATERIALIZED (SELECT unnest($1::uuid[]) AS id),
 excluded_emitters AS MATERIALIZED (SELECT unnest($2::uuid[]) AS id),
 qualified AS (
SELECT ip.node_id
FROM candidates c CROSS JOIN LATERAL (
 SELECT ip.node_id,ip.frontmatter_valid FROM indexed_pages ip
 WHERE ip.node_id=c.id AND ip.notebook_id=$3
  AND ip.extractor=$4 LIMIT 1
) ip
WHERE true
 AND NOT EXISTS (
  SELECT 1 FROM page_links l CROSS JOIN LATERAL (
   SELECT e.node_id FROM indexed_pages e
   WHERE e.node_id=l.source_id AND e.notebook_id=$3
    AND e.extractor=$4
    AND l.notebook_id=$3 AND NOT l.resolved_asset
    AND l.source_id<>ip.node_id
    AND e.node_id NOT IN (SELECT id FROM excluded_emitters)
   LIMIT 1
  ) current_emitter
  WHERE l.resolved_id=ip.node_id
 )
LIMIT 10000
)
SELECT count(*)::bigint FROM qualified
`

